"""Build a self-contained coverflow prototype from the real photographs.

Images are embedded as base64 so the file works anywhere with no server and no
sibling assets. Downscaled to 900px first, which is plenty for a card that
renders around 300px wide and keeps the file near a megabyte.
"""
import base64, io, json, os
from PIL import Image

# Where the canopy is in each frame, found by saturation and ranked by score
# rather than by area: the largest saturated blob is usually sunlit ground, the
# strongest one is the wing. Verified against every photograph by eye.
WINGS = json.load(open("/tmp/wings.json"))

CLOUD1 = ""
CLOUD2 = ""
CLOUD3 = ""


SHOTS = [
    ("assets/destinations/kenya/hero/longonot.jpg",     "Mount Longonot",  "An intact crater rim, 2,776m"),
    ("assets/destinations/kenya/hero/kerio-valley.jpg", "Kerio Valley",    "The base, and where the records are chased"),
    ("assets/destinations/kenya/hero/equator.jpg",      "The Equator",     "Crossing zero latitude from the air"),
    ("assets/destinations/kenya/hero/north-kenya.jpg",  "Northern Kenya",  "Storm light over the escarpment"),
    ("assets/destinations/kenya/hero/chyulu-hills.jpg", "Chyulu Hills",    "Between Tsavo and Amboseli"),
    ("assets/images/kenya-hero.jpg",                    "Caption needed",  "kenya-hero.jpg"),
    ("assets/images/kenya-high.jpg",                    "Caption needed",  "kenya-high.jpg"),
    ("assets/images/kenya-launch.jpg",                  "Caption needed",  "kenya-launch.jpg"),
    ("assets/images/kenya-ridge.jpg",                   "Caption needed",  "kenya-ridge.jpg"),
    ("assets/images/kenya-slope.jpg",                   "Caption needed",  "kenya-slope.jpg"),
    ("assets/images/kenya-3.jpg",                       "Caption needed",  "kenya-3.jpg"),
]

cards, total = [], 0
for path, title, sub in SHOTS:
    if not os.path.exists(path):
        continue
    im = Image.open(path).convert("RGB")
    im.thumbnail((900, 900), Image.LANCZOS)
    buf = io.BytesIO()
    im.save(buf, "JPEG", quality=74, optimize=True, progressive=True)
    total += buf.tell()
    wx, wy = WINGS.get(os.path.basename(path), [50, 50])[:2]
    # clamp, so a wing near an edge cannot pull the crop off the picture
    wx = min(85, max(15, wx)); wy = min(85, max(15, wy))
    cards.append((base64.b64encode(buf.getvalue()).decode(), title, sub, wx, wy))

slides = "\n".join(
    f'''<figure class="cf-card" data-i="{i}">
      <img src="data:image/jpeg;base64,{b}" alt="{t}"
        style="object-position:{wx}% {wy}%">
    </figure>''' for i, (b, t, s, wx, wy) in enumerate(cards))

caps = "\n".join(
    f'<div class="cf-cap" data-i="{i}"><h3>{t}</h3><i></i><p>{s}</p></div>'
    for i, (b, t, s, wx, wy) in enumerate(cards))

ticks = "".join(f'<button class="cf-tick" data-i="{i}" aria-label="Photograph {i+1}"></button>'
                for i in range(len(cards)))

full = "\n".join(f'<img class="cf-full" data-i="{i}" src="data:image/jpeg;base64,{b}" alt="{t}">'
                 for i, (b, t, s, wx, wy) in enumerate(cards))

bgs = "\n".join(f'<img class="cf-bg" data-i="{i}" src="data:image/jpeg;base64,{b}" alt="">'
                for i, (b, t, s, wx, wy) in enumerate(cards))

html = f'''<!doctype html><meta charset="utf-8"><title>Kenya coverflow prototype</title>
<style>
 :root{{--bg:#141519;--orange:#ff7517;--white:#fff;--gray:#8f95a3;
   --ar:2/3;--cardw:26%;--gap:.58;--rot:42deg;--fall:.085;--depth:150px;--tilt:9}}
 *{{box-sizing:border-box}}
 body{{margin:0;background:var(--bg);color:var(--white);
   font-family:"DM Sans",system-ui,sans-serif;overflow-x:hidden}}
 .cf{{position:relative;width:100%;height:82vh;min-height:520px;overflow:hidden;
   display:flex;align-items:center;justify-content:center;isolation:isolate}}
 .cf-bgwrap{{position:absolute;inset:-8%;z-index:0}}
 .cf-bg{{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;
   filter:blur(40px) saturate(1.25) brightness(.62);opacity:0;
   transition:opacity 900ms ease;transform:scale(1.12)}}
 .cf-bg.on{{opacity:1}}
 /* Clouds. Three layers at different rates, driven by one passive scroll
    listener through rAF, which is cheap enough for a phone. Transform only, so
    nothing here triggers layout. */
 .cf-clouds{{position:absolute;inset:-22% -12%;z-index:1;pointer-events:none;
   overflow:hidden}}
 .cf-cloud{{position:absolute;left:-6%;width:112%;height:auto;opacity:.5;
   will-change:transform;mix-blend-mode:screen}}
 .cf-cloud:nth-child(1){{top:2%}} .cf-cloud:nth-child(2){{top:46%;opacity:.34}}
 .cf-cloud:nth-child(3){{top:72%;opacity:.26}}
 @media(max-width:700px){{.cf-cloud{{opacity:.34}}}}
 .cf-lb{{position:fixed;inset:0;z-index:60;background:rgba(10,10,12,.94);
   display:none;place-items:center;padding:clamp(1rem,4vw,3rem);cursor:zoom-out}}
 .cf-lb.on{{display:grid}}
 .cf-lb img{{max-width:100%;max-height:100%;object-fit:contain;display:block;
   box-shadow:0 40px 90px rgba(0,0,0,.6)}}
 .cf-lb-x{{position:absolute;top:1rem;right:1.2rem;width:42px;height:42px;
   border-radius:50%;border:1px solid rgba(255,255,255,.35);background:none;
   color:#fff;font-size:1.1rem;cursor:pointer}}
 .cf-full{{display:none}} .cf-full.on{{display:block}}
 .cf-scrim{{position:absolute;inset:0;z-index:1;pointer-events:none;
   background:radial-gradient(120% 90% at 50% 45%,rgba(20,21,25,.15) 0,rgba(20,21,25,.82) 80%)}}
 .cf-stage{{position:relative;z-index:2;width:100%;height:100%;
   perspective:1400px;perspective-origin:var(--px,50%) var(--py,50%)}}
 .cf-tilt{{position:absolute;inset:0;transform-style:preserve-3d;will-change:transform}}
 .cf-card{{position:absolute;left:50%;top:50%;margin:0;width:var(--cardw);
   aspect-ratio:var(--ar);overflow:hidden;background:#0d0e11;
   transform-style:preserve-3d;will-change:transform;cursor:pointer;
   box-shadow:0 30px 70px rgba(0,0,0,.55);
   transition:transform 780ms cubic-bezier(.4,.02,.16,1),
              filter 780ms ease, opacity 600ms ease}}
 .cf-card img{{width:100%;height:100%;object-fit:cover;display:block;
   -webkit-user-drag:none;user-select:none}}
 .cf-cap{{position:absolute;z-index:3;left:50%;top:50%;transform:translate(-50%,-50%);
   text-align:center;pointer-events:none;opacity:0;transition:opacity 450ms ease;
   text-shadow:0 2px 26px rgba(0,0,0,.75);width:min(92%,42rem)}}
 .cf-cap.on{{opacity:1}}
 .cf-cap h3{{font-family:Poppins,system-ui,sans-serif;font-weight:700;
   font-size:clamp(1.5rem,3.6vw,2.7rem);letter-spacing:.02em;margin:0;
   text-transform:uppercase;line-height:1.08}}
 .cf-cap i{{display:block;width:60px;height:1px;background:rgba(255,255,255,.65);
   margin:1rem auto}}
 .cf-cap p{{margin:0;font-size:clamp(.78rem,1.3vw,.94rem);letter-spacing:.12em;
   color:rgba(255,255,255,.82)}}
 .cf-arrow{{position:absolute;z-index:4;top:50%;transform:translateY(-50%);
   width:46px;height:46px;border-radius:50%;border:1px solid rgba(255,255,255,.3);
   background:rgba(20,21,25,.35);color:#fff;font-size:1.1rem;cursor:pointer;
   display:grid;place-items:center;transition:border-color .2s,background .2s}}
 .cf-arrow:hover{{border-color:var(--orange);background:rgba(20,21,25,.7)}}
 .cf-prev{{left:clamp(.6rem,3vw,2.4rem)}} .cf-next{{right:clamp(.6rem,3vw,2.4rem)}}
 .cf-ticks{{position:absolute;z-index:4;top:clamp(1rem,3vh,2rem);left:50%;
   transform:translateX(-50%);display:flex;gap:9px}}
 .cf-tick{{width:26px;height:2px;border:0;padding:0;cursor:pointer;
   background:rgba(255,255,255,.28);transition:background .3s}}
 .cf-tick.on{{background:var(--orange)}}
 .panel{{max-width:1060px;margin:26px auto 60px;padding:0 20px;color:var(--gray);
   font-size:13.5px;line-height:1.7}}
 .panel h4{{color:#fff;font-size:13px;letter-spacing:.14em;text-transform:uppercase;
   margin:0 0 .7rem}}
 .row{{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:1.2rem}}
 .row button{{background:none;border:1px solid rgba(255,255,255,.22);color:#fff;
   padding:8px 14px;font:inherit;font-size:12.5px;letter-spacing:.08em;cursor:pointer}}
 .row button.on{{border-color:var(--orange);color:var(--orange)}}
 @media(prefers-reduced-motion:reduce){{.cf-card,.cf-cap,.cf-bg{{transition:none!important}}}}
</style>

<div class="cf" id="cf">
  <div class="cf-bgwrap">{bgs}</div>
  <div class="cf-clouds" aria-hidden="true">
    <img class="cf-cloud" data-sp="-0.16" src="data:image/webp;base64,{CLOUD1}" alt="">
    <img class="cf-cloud" data-sp="0.10" src="data:image/webp;base64,{CLOUD2}" alt="">
    <img class="cf-cloud" data-sp="-0.30" src="data:image/webp;base64,{CLOUD3}" alt="">
  </div>
  <div class="cf-scrim"></div>
  <div class="cf-stage" id="stage"><div class="cf-tilt" id="tilt">{slides}</div></div>
  {caps}
  <div class="cf-ticks">{ticks}</div>
  <button class="cf-arrow cf-prev" aria-label="Previous">&#10094;</button>
  <button class="cf-arrow cf-next" aria-label="Next">&#10095;</button>
</div>
<div class="cf-lb" id="lb" role="dialog" aria-modal="true" aria-label="Full photograph">
  <button class="cf-lb-x" id="lbx" aria-label="Close">&#10005;</button>
  {full}
</div>

<div class="panel">
  <h4>Card shape &mdash; this is the decision</h4>
  <div class="row" id="ar">
    <button data-ar="2/3" data-keep="44" class="on">2:3 portrait &middot; keeps 44% of the frame</button>
    <button data-ar="4/5" data-keep="53">4:5 &middot; keeps 53%</button>
    <button data-ar="1/1" data-keep="67">1:1 square &middot; keeps 67%</button>
    <button data-ar="3/2" data-keep="100">3:2 landscape &middot; keeps all of it</button>
  </div>
  <h4>Cursor tilt</h4>
  <div class="row" id="tilt">
    <button data-tilt="0">Off</button>
    <button data-tilt="5">Subtle</button>
    <button data-tilt="9" class="on">Reference</button>
    <button data-tilt="15">Strong</button>
  </div>
  <h4>Spread &mdash; how much of each neighbour shows</h4>
  <div class="row" id="gap">
    <button data-gap=".42">Tight</button>
    <button data-gap=".58" class="on">Reference</button>
    <button data-gap=".74">Open</button>
    <button data-gap=".92">Wide</button>
  </div>
  <h4>Depth</h4>
  <div class="row" id="rot">
    <button data-rot="42deg" class="on">Strong</button>
    <button data-rot="32deg">Reference</button>
    <button data-rot="20deg">Subtle</button>
    <button data-rot="0deg">Flat</button>
  </div>
  <p>Loops in both directions, so there is no end to hit. Move the cursor to lean the scene. Drag sideways, use the arrows or the keyboard. Click a card to bring it forward; click the front one to open it full size.
     Switch the card shape to see what each crop costs the photographs.</p>
</div>

<script>
const cf=document.getElementById('cf'), stage=document.getElementById('stage');
const cards=[...document.querySelectorAll('.cf-card')];
const caps=[...document.querySelectorAll('.cf-cap')];
const ticks=[...document.querySelectorAll('.cf-tick')];
const bgs=[...document.querySelectorAll('.cf-bg')];
const N=cards.length, VIS=Math.min(5,Math.floor(N/2)); let at=Math.floor(N/2);
const css=getComputedStyle(document.documentElement);
function layout(){{
  const gap=parseFloat(css.getPropertyValue('--gap'));
  const rot=css.getPropertyValue('--rot').trim();
  const fall=parseFloat(css.getPropertyValue('--fall'));
  const depth=parseFloat(css.getPropertyValue('--depth'));
  // Spread measured against the STAGE, not the card. Based on card width it
  // changed every time the card shape changed, which is the drift you spotted.
  const unit=cf.getBoundingClientRect().width*0.30;
  cards.forEach((c,i)=>{{
    // shortest way round the ring, so the stack never runs out on either side
    let d=((i-at)%N+N)%N; if(d>N/2) d-=N;
    const a=Math.abs(d), s=Math.sign(d);
    const hidden=a>=VIS;
    const x=d*unit*gap;
    const ry=d===0?'0deg':(s<0?rot:'-'+rot);
    const sc=Math.max(.45,1-a*fall);
    const z=-a*depth;
    c.style.transform=`translate(-50%,-50%) translateX(${{x}}px) translateZ(${{z}}px) rotateY(${{ry}}) scale(${{sc}})`;
    c.style.zIndex=String(100-a);
    c.style.filter=`brightness(${{d===0?1:Math.max(.3,1-a*.22)}})`;
    c.style.opacity=hidden?'0':String(Math.max(.25,1-a*.16));
    c.style.pointerEvents=hidden?'none':'auto';
    // a card only jumps across the ring while it is invisible, so kill the
    // transition there or it flies the width of the screen to get home
    c.style.transitionProperty=hidden?'none':'transform,filter,opacity';
  }});
  caps.forEach((e,i)=>e.classList.toggle('on',i===at));
  ticks.forEach((e,i)=>e.classList.toggle('on',i===at));
  bgs.forEach((e,i)=>e.classList.toggle('on',i===at));
}}
function go(n){{ at=((n%N)+N)%N; layout(); }}
cards.forEach((c,i)=>c.addEventListener('click',()=>{{
  if(moved&&Math.abs(moved)>6) return;            // that was a drag
  let d=((i-at)%N+N)%N; if(d>N/2) d-=N;
  if(d===0) openLb(i); else go(at+d);             // front card opens full size
}}));
const lb=document.getElementById('lb');
const fulls=[...document.querySelectorAll('.cf-full')];
function openLb(i){{
  fulls.forEach((f,n)=>f.classList.toggle('on',n===i));
  lb.classList.add('on'); document.body.style.overflow='hidden';
}}
function closeLb(){{ lb.classList.remove('on'); document.body.style.overflow=''; }}
lb.addEventListener('click',closeLb);
document.getElementById('lbx').addEventListener('click',e=>{{e.stopPropagation();closeLb();}});
addEventListener('keydown',e=>{{ if(e.key==='Escape') closeLb(); }});
ticks.forEach((t,i)=>t.addEventListener('click',()=>go(i)));
document.querySelector('.cf-prev').addEventListener('click',()=>go(at-1));
document.querySelector('.cf-next').addEventListener('click',()=>go(at+1));
addEventListener('keydown',e=>{{ if(e.key==='ArrowRight')go(at+1);
  else if(e.key==='ArrowLeft')go(at-1); else return; e.preventDefault(); }});
let x0=null,moved=0;
cf.addEventListener('pointerdown',e=>{{ if(e.target.closest('button'))return;
  x0=e.clientX; moved=0; e.preventDefault(); }});
addEventListener('pointermove',e=>{{ if(x0!==null) moved=e.clientX-x0; }});
addEventListener('pointerup',()=>{{ if(x0===null)return;
  if(Math.abs(moved)>45) go(at+(moved<0?1:-1)); x0=null; }});
addEventListener('pointercancel',()=>x0=null);
document.getElementById('ar').addEventListener('click',e=>{{
  const b=e.target.closest('[data-ar]'); if(!b)return;
  document.querySelectorAll('#ar button').forEach(x=>x.classList.remove('on'));
  b.classList.add('on');
  document.documentElement.style.setProperty('--ar',b.dataset.ar);
  document.documentElement.style.setProperty('--cardw', b.dataset.ar==='3/2'?'34%':
    b.dataset.ar==='1/1'?'28%':'26%');
  requestAnimationFrame(layout);
}});
document.getElementById('tilt').addEventListener('click',e=>{{
  const b=e.target.closest('[data-tilt]'); if(!b)return;
  document.querySelectorAll('#tilt button').forEach(x=>x.classList.remove('on'));
  b.classList.add('on');
  document.documentElement.style.setProperty('--tilt',b.dataset.tilt);
}});
document.getElementById('gap').addEventListener('click',e=>{{
  const b=e.target.closest('[data-gap]'); if(!b)return;
  document.querySelectorAll('#gap button').forEach(x=>x.classList.remove('on'));
  b.classList.add('on');
  document.documentElement.style.setProperty('--gap',b.dataset.gap);
  layout();
}});
document.getElementById('rot').addEventListener('click',e=>{{
  const b=e.target.closest('[data-rot]'); if(!b)return;
  document.querySelectorAll('#rot button').forEach(x=>x.classList.remove('on'));
  b.classList.add('on');
  document.documentElement.style.setProperty('--rot',b.dataset.rot);
  layout();
}});
// Cursor tilt. The reference leans the whole scene as the pointer moves, which
// is what gives it depth even when the cards themselves are nearly flat.
let wantX=0,wantY=0,haveX=0,haveY=0;
const tilt=document.getElementById('tilt');
cf.addEventListener('pointermove',e=>{{
  const r=cf.getBoundingClientRect();
  wantX=((e.clientX-r.left)/r.width)*2-1;
  wantY=((e.clientY-r.top)/r.height)*2-1;
}});
cf.addEventListener('pointerleave',()=>{{wantX=0;wantY=0;}});
const calm=matchMedia('(prefers-reduced-motion: reduce)');
function frame(){{
  const amt=parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--tilt'))||0;
  haveX+=(wantX-haveX)*0.065; haveY+=(wantY-haveY)*0.065;
  if(!calm.matches){{
    tilt.style.transform=`rotateY(${{(haveX*amt).toFixed(2)}}deg) `+
      `rotateX(${{(-haveY*amt*0.55).toFixed(2)}}deg) translateX(${{(-haveX*amt*2.6).toFixed(1)}}px)`;
    cf.style.setProperty('--px',(50+haveX*14).toFixed(1)+'%');
    cf.style.setProperty('--py',(50+haveY*8).toFixed(1)+'%');
  }}
  requestAnimationFrame(frame);
}}
frame();

// Cloud parallax, tied to the section's own position in the viewport so it
// reads while scrolling the page rather than only inside the component.
const clouds=[...document.querySelectorAll('.cf-cloud')];
let ticking=false;
function drift(){{
  ticking=false;
  const r=cf.getBoundingClientRect();
  const p=(r.top+r.height/2-innerHeight/2)/innerHeight;   // -1..1 through the viewport
  clouds.forEach(c=>{{
    const sp=parseFloat(c.dataset.sp)||0;
    c.style.transform=`translate3d(${{(p*sp*90).toFixed(1)}}px,${{(p*sp*170).toFixed(1)}}px,0)`;
  }});
}}
addEventListener('scroll',()=>{{ if(!ticking){{ticking=true;requestAnimationFrame(drift);}} }},{{passive:true}});
drift();
addEventListener('resize',layout);
document.documentElement.style.setProperty('--ar','2/3');
document.documentElement.style.setProperty('--cardw','26%');
document.documentElement.style.setProperty('--rot','42deg');
document.documentElement.style.setProperty('--tilt','9');
layout();
</script>'''

open("/mnt/user-data/outputs/coverflow-prototype.html", "w").write(html)
print(f"{len(cards)} photographs, {total//1024}KB of image, file {len(html)//1024}KB")
